class Solution:

    def findWords(self, board, words):

        rows = len(board)
        cols = len(board[0])
        result = []

        def exists(word):

            def dfs(r, c, index):
                if index == len(word):
                    return True

                if (
                    r < 0 or r >= rows or c < 0 or c >= cols
                    or board[r][c] != word[index]
                ):
                    return False

                temp = board[r][c]
                board[r][c] = "#"

                found = (
                    dfs(r + 1, c, index + 1)
                    or dfs(r - 1, c, index + 1)
                    or dfs(r, c + 1, index + 1)
                    or dfs(r, c - 1, index + 1)
                )

                board[r][c] = temp
                return found

            for r in range(rows):
                for c in range(cols):
                    if board[r][c] == word[0]:
                        if dfs(r, c, 0):
                            return True

            return False

        for word in words:
            if exists(word):
                result.append(word)

        return result

